from __future__ import annotations

from datetime import date
import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class LowVolatilityTilting(Strategy):
    rationale = (
        "Low-volatility stocks tend to outperform high-volatility stocks over time. This "
        "strategy aims to exploit this by constructing a portfolio of low-volatility stocks."
    )

    def __init__(self, window: int = 20) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.is_empty():
            return Signal(information_available_at=stamp, weights={})

        # Calculate the historical volatility for each stock
        volatility = (
            history.select(
                [
                    pl.col("symbol"),
                    (pl.col("adj_close").std() / pl.col("adj_close").mean()).alias("volatility")
                ]
            ).group_by("symbol")
            .agg(pl.col("volatility").mean().alias("mean_volatility"))
        )

        # Get the symbols with lowest volatility
        low_vol_symbols = [row[0] for row in volatility.sort("mean_volatility", descending=False).select("symbol").to_numpy()]

        if not low_vol_symbols:
            return Signal(information_available_at=stamp, weights={})

        weight = 1.0 / len(low_vol_symbols)
        return Signal(
            information_available_at=stamp,
            weights={s: weight for s in low_vol_symbols}
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
